//
// Durr-Rapaport-Theyssier (arXiv cs/0210008, TCS 322 (2004) 355-368) classify
// the 256 elementary rules by the growth of d_n.  Their definition, fetched
// from ar5iv:
//
//   M_0^n(i,j) := f^n(b_i^<-, 0, b_j)     (centre cell fixed to 0)
//   M_1^n(i,j) := f^n(b_i^<-, 1, b_j)     (centre cell fixed to 1)
//   d_n := max of the four counts { #distinct rows of M_0^n,
//                                   #distinct cols of M_0^n,
//                                   #distinct rows of M_1^n,
//                                   #distinct cols of M_1^n }
//
// where b_k is the binary representation of k on exactly n bits, Alice holds
// the n cells left of the origin and Bob the n cells right of it, and the
// value read is the origin cell after n steps.
//
// log2 d_n is exactly the ONE-WAY communication complexity of the prediction
// problem, and it is also a Neciporuk term: the number of distinct subfunctions
// obtained by fixing Alice's block.
//
// Method: bit-parallel over Bob's 2^n inputs.  Each cell of the configuration
// carries a 2^n-bit mask, one bit per Bob assignment; one CA step is bitwise.
// So one Alice input costs n steps x width x (2^n/32) words, and the whole
// row set costs 2^n of those.  Exact, exhaustive, no sampling.

const W32 = 32;

function makeMask(words) { return new Uint32Array(words); }

function andNot3(out, a, b, c, sa, sb, sc, words) {
  // out |= (sa ? a : ~a) & (sb ? b : ~b) & (sc ? c : ~c)
  for (let w = 0; w < words; w++) {
    const x = sa ? a[w] : ~a[w];
    const y = sb ? b[w] : ~b[w];
    const z = sc ? c[w] : ~c[w];
    out[w] |= x & y & z;
  }
}

// One CA step on an array of masks.  cells[i] is the mask for cell i;
// outside the array the background is the mask `bg`.
function stepMasks(rule, cells, width, words, bg) {
  const out = [];
  for (let i = 0; i < width; i++) out.push(makeMask(words));
  for (let i = 0; i < width; i++) {
    const l = i - 1 >= 0 ? cells[i - 1] : bg;
    const c = cells[i];
    const r = i + 1 < width ? cells[i + 1] : bg;
    for (let nb = 0; nb < 8; nb++) {
      if (((rule >> nb) & 1) === 0) continue;
      andNot3(out[i], l, c, r, (nb >> 2) & 1, (nb >> 1) & 1, nb & 1, words);
    }
  }
  return out;
}

// Count distinct rows of M_c^n, i.e. distinct functions Bob's input -> centre
// value, as Alice's input ranges over 2^n.  If `swap` is true, the roles are
// exchanged, which counts distinct COLUMNS instead.
function distinctRows(rule, n, centre, swap) {
  const words = Math.max(1, (1 << n) / W32);
  const pad = n + 1;
  const width = 2 * n + 1 + 2 * pad;
  const origin = pad + n;
  const ZERO = makeMask(words);
  const ONES = makeMask(words);
  for (let w = 0; w < words; w++) ONES[w] = 0xffffffff | 0;

  // the free side's cell masks: free cell k (k = 0..n-1) is bit k of the index
  const freeMask = [];
  for (let k = 0; k < n; k++) {
    const m = makeMask(words);
    for (let idx = 0; idx < 1 << n; idx++) {
      if ((idx >> k) & 1) m[idx >>> 5] |= 1 << (idx & 31);
    }
    freeMask.push(m);
  }

  const seen = new Set();
  const A = 1 << n;
  for (let a = 0; a < A; a++) {
    const cells = [];
    for (let i = 0; i < width; i++) cells.push(ZERO);
    // fixed side (Alice if !swap) occupies cells -n..-1 = indices pad..pad+n-1
    // free side (Bob if !swap) occupies cells 1..n = indices origin+1..origin+n
    for (let k = 0; k < n; k++) {
      const fixedIdx = swap ? origin + 1 + k : pad + k;
      const freeIdx = swap ? pad + k : origin + 1 + k;
      cells[fixedIdx] = (a >> k) & 1 ? ONES : ZERO;
      cells[freeIdx] = freeMask[k];
    }
    cells[origin] = centre ? ONES : ZERO;
    let cur = cells;
    for (let t = 0; t < n; t++) cur = stepMasks(rule, cur, width, words, ZERO);
    seen.add(Buffer.from(cur[origin].buffer.slice(0)).toString('latin1'));
  }
  return seen.size;
}

function dn(rule, n) {
  return Math.max(
    distinctRows(rule, n, 0, false),
    distinctRows(rule, n, 0, true),
    distinctRows(rule, n, 1, false),
    distinctRows(rule, n, 1, true)
  );
}

