  console.log(`\nd_${NB}: max ${order[0][0]} (rule ${order[0][1]}); rule 30 = ${last[30]}, rank ${order.findIndex((p) => p[1] === 30) + 1} of 256`);
  console.log('top 12: ' + order.slice(0, 12).map((p) => `${p[1]}:${p[0]}`).join(', '));
  console.log(`rules attaining the ceiling 2^${NB} = ${1 << NB}: ` + last.map((v, i) => [v, i]).filter((p) => p[0] === (1 << NB)).map((p) => p[1]).join(', '));
} else if (mode === 'deep') {
